sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    let mobile = {};
    let phone = {};
    let email = {};
    let city = {};
    let state = {};

    let contacts = [];

    mobile.label = "Mobile phone";
    mobile.value = api.data.Group_Manager.results[0].manager._reference.mobile.displayValue || "N/A";
    contacts.push(mobile);

    phone.label = "Phone";
    phone.value = api.data.Group_Manager.results[0].manager._reference.phone.displayValue || "N/A";
    contacts.push(phone);

    email.label = "Email";
    email.value = api.data.Group_Manager.results[0].manager._reference.email.displayValue || "N/A";
    contacts.push(email);

    city.label = "City";
    city.value = api.data.Group_Manager.results[0].manager._reference.city.displayValue || "N/A";
    contacts.push(city);

    state.label = "State";
    state.value = api.data.Group_Manager.results[0].manager._reference.state.displayValue || "N/A";
    contacts.push(state);

    console.log(contacts, "contacts");

    return contacts;
}
